  const donutData:ChartData={chart:{margin:{top:0,bottom:0,left:0,right:0}},legend:{enabled:false},colors:palette,series:{data:[{type:'"'pie',name:'Источники',innerRadius:'76%',borderWidth:4,borderColor:'var(--g-color-base-background)',dataLabels:{enabled:false},data:[{name:'Прямые переходы',value:42},{name:'Поисковые системы',value:28},{name:'Социальные сети',value:18},{name:'Другие',value:12}]}]}};
  const barData:ChartData={chart:{margin:{top:8,bottom:4,left:0,right:0}},legend:{enabled:false},series:{data:[{type:'bar-x',name:'Пользователи',color:palette[0],borderRadius:4,barMaxWidth:24,data:[42,59,47,70,55,86,65].map((y,x)=>({x,y:Math.round(y*factor),color:x===5?palette[0]:'var(--g-color-base-utility-light)'}))}]},xAxis:{type:'category',categories:['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],grid:{enabled:false}},yAxis:[{min:0,grid:{enabled:true},ticks:{pixelInterval:48},labels:{format:{type:'custom',formatter:v=>"'`${v}`}}}]};
  return <article className={`widget ${isMetric?'"'metric':''} widget-"'${kind} ${editMode?'"'widget-editable':''}"'`}>
    <div className="widget-heading">
      <div className="widget-drag" title={editMode?'"'Перетащите виджет':'Включите режим настройки'}><span className={isMetric?'metric-label':'widget-title'}>{spec.title}</span>{editMode&&<Glyph data={Grip} size={14}/>}</div>
      {isMetric ? <span className={"'`metric-icon metric-icon-${kind}`}><Glyph data={spec.icon} size={17}/></span> : <DropdownMenu defaultSwitcherProps={{view:'"'flat',size:'s','aria-label':"'`Меню: ${spec.title}`}} items={[{text:'"'Удалить виджет',action:()=>remove(id),theme:'danger'}]}/>}
    </div>
